using SparkFlow.Server.Application.Services; namespace SparkFlow.Server.Application.Features.Sessions.CompleteSession; public sealed class CompleteSessionHandler { private readonly SessionService _service; public CompleteSessionHandler(SessionService service){_service=service;} public Task<bool> Handle(CompleteSessionCommand command, CancellationToken cancellationToken=default)=>_service.CompleteAsync(command.SessionId,cancellationToken);}
